/* ═════════ 11 · SAISIES (data-afx) ═════════ */
export function chiffrageInput(el,ctx){const d=el.dataset;const a=A.cur();if(d.afprix!==undefined&&el.files){const f=el.files[0];el.value='';if(f&&ctx.canEdit)prixImportFile(f,ctx);return true;}
  if(d.afx===undefined)return false;const render=()=>{if(ctx.render)ctx.render();};const val=el.type==='checkbox'?el.checked:(el.type==='number'?(el.value===''?'':+el.value):(el.tagName==='SELECT'&&/^-?\d+(\.\d+)?$/.test(el.value)?+el.value:el.value)); /* un DN choisi dans une liste reste un nombre */
  const [kind,...rest]=d.afx.split('§');
  if(kind==='cmpsite'){CS.cmpSite=el.value;CS.cmpPhase='';render();return true;}if(kind==='cmpphase'){CS.cmpPhase=el.value;render();return true;}if(kind==='bq'){CS.q=el.value;render();return true;}
  if(!ctx.canEdit){if(A.toast)A.toast('Lecture seule');return true;}
  if(kind==='e'){if(!a)return true;const path=rest.join('§');withCh(a,ch=>{const zz=fullEtude(ch.etudes[Math.min(CS.ei,ch.etudes.length-1)]);setP(zz,path,val);ch.etudes[Math.min(CS.ei,ch.etudes.length-1)]=zz;});render();return true;}
  if(kind==='ch'){if(!a)return true;const ch=Object.assign({},a.chiffrage||{});const k=rest[0];if(k==='marge')ch.marge=val===''?null:num(val)/100;else if(k==='rcfa')ch.rcfa=val===''?null:num(val)/100;A.affSet(a.num,{chiffrage:ch});render();return true;}
  if(kind==='pt'){if(!a)return true;const pt=clone(a.points||{});setP(pt,rest.join('§'),val);A.affSet(a.num,{points:pt});render();return true;}
  if(kind==='hors'){if(!a)return true;const ch=Object.assign({},a.chiffrage||{});ch.horsMl=Object.assign({},ch.horsMl||{});ch.horsMl[rest[0]]=!!val;A.affSet(a.num,{chiffrage:ch});render();return true;}
  const base=prixBase();if(!base)return true;
  if(kind==='b'){const b=clone(base);let x=b;for(let i=0;i<rest.length-1;i++){const k=rest[i];if(x[k]===undefined||x[k]===null)x[k]=/^\d+$/.test(rest[i+1])?[]:{};x=x[k];}x[rest[rest.length-1]]=val;prixSave(b);render();return true;}
  if(kind==='ov'){const [pid,dn,item,field]=rest;const b=clone(base);b.over=b.over||{};b.over[pid]=b.over[pid]||{};b.over[pid][dn]=b.over[pid][dn]||{};b.over[pid][dn][item]=Object.assign({},b.over[pid][dn][item]||{});if(val==='')delete b.over[pid][dn][item][field];else b.over[pid][dn][item][field]=val;prixSave(b);render();return true;}
  if(kind==='db'){const [id,...path]=rest;const pn=paniersDB().find(x=>x.id===id);if(!pn)return true;const patch={};if(path.length===1)patch[path[0]]=val;else{const items=clone(pn.items||[]);setP({items},path.join('.'),val);patch.items=items;}regSet('panier',id,patch);render();return true;}
  return false;}
/* ═════════ 12 · IMPORT DU CLASSEUR ═════════ */
export async function prixImportFile(file,ctx){const say=t=>A.toast&&A.toast(t);say('Lecture du classeur…');
  try{const base=await parsePrixWorkbook(file,{name:file.name});delete base.op.blocks; /* le dump brut des blocs ne sert qu'à l'analyse : pas en base */
    const old=prixBase();if(old&&old.over)base.over=old.over;base.importedAt=new Date().toISOString();base.importedBy=A.userName?A.userName():'';
    if(old&&!confirm('Remplacer la base de prix actuelle ('+(old.version||'?')+(old.at?' du '+dFR(old.at):'')+') par ce classeur ('+(base.version||'?')+(base.at?' du '+dFR(base.at):'')+') ?'))return;
    prixSave(base);CS.view='base';CS.baseTab='import';say('Base de prix importée : '+(base.version||'')+' · '+(base.mo.cad||[]).length+' DN · '+(base.op.paniers||[]).length+' paniers · '+Object.keys(base.fo.params).length+' paramètres');if(ctx.render)ctx.render();}
  catch(e){console.warn(e);say('Classeur illisible : '+(e.message||e));}}
/* ═════════ 13 · FICHE DE CHIFFRAGE IMPRIMABLE (v2) ═════════ */
export function chiffragePrint2HTML(a){const base=prixBase();const C=calcAffaireV2(a,base);const E=C.etudes;
  const zones=E.map((e,i)=>{const T=e.r.T||{};const rows=(e.r.detail.dn||{}).rows||[];return `<h2>${esc(e.z.nom||'Zone '+(i+1))}</h2><table class="em"><tr><th>DN</th><th>Soudures</th><th>ml</th><th>€/pouce</th><th>Soudure</th><th>€/manchon</th><th>Manchons</th><th>j S</th><th>j M</th></tr>${rows.map(r=>`<tr><td>DN ${r.dn}</td><td>${nb(r.J)}</td><td>${nb(r.ml)}</td><td>${nb(r.pPouce,2)}</td><td>${nb(r.soud)}</td><td>${nb(r.pManch,2)}</td><td>${nb(r.manch)}</td><td>${nb(r.qS,1)}</td><td>${nb(r.qM,1)}</td></tr>`).join('')}</table><table class="em"><tr><th>Poste</th><th>Achat €</th></tr>${POSTES.filter(p=>!p[3]).map(p=>{const v=(e.r.postes[p[0]]||{}).achat||0;return v?`<tr><td>${esc(p[1])}</td><td>${nb(v)}</td></tr>`:'';}).join('')}<tr><td><b>Total zone</b></td><td><b>${nb(Object.values(e.r.postes).reduce((s,p)=>s+p.achat,0))}</b></td></tr></table>`;}).join('');
  const recap=`<h2>Récap prix</h2><table class="em"><tr><th>Poste</th>${E.map(e=>`<th>${esc(e.z.nom||'')}</th>`).join('')}<th>Achat</th><th>Vente</th></tr>${C.postes.map(p=>p.tete?`<tr><td colspan="${E.length+3}"><b>${esc(p.label)}</b></td></tr>`:(p.achat?`<tr><td>${esc(p.label)}</td>${p.par.map(x=>`<td>${x?nb(x):''}</td>`).join('')}<td>${nb(p.achat)}</td><td>${nb(p.vente)}</td></tr>`:'')).join('')}<tr><td><b>Total</b></td>${E.map(()=>'<td></td>').join('')}<td><b>${nb(C.achat)}</b></td><td><b>${nb(C.vente)}</b></td></tr></table>
    <table class="em"><tr><td>Prix d'achat</td><td>${eur(C.achat)}</td></tr><tr><td>Marge ${nb(C.marge*100,1)} %</td><td>${eur(C.margeEur)}</td></tr><tr><td>RCFA ${nb(C.rcfaPct*100,1)} %</td><td>${eur(C.rcfa)}</td></tr><tr><td><b>Prix de vente HT</b></td><td><b>${eur(C.vente)}</b></td></tr><tr><td>€ / ml</td><td>${nb(C.parMl,2)}${C.parMlHors!==C.parMl?' (hors postes « hors » : '+nb(C.parMlHors,2)+')':''}</td></tr></table>`;
  return A.docHTML({title:'Chiffrage — '+(a.nom||a.num),kicker:'Commerce · fiche de chiffrage v'+(a.chiffrageV||1)+' · '+esc(a.num),sub:esc(a.client||'')+(a.ville?' · '+esc(a.ville):''),meta:[['Affaire',esc(a.num)],['Prix de vente HT',eur(C.vente)],['€ / ml',C.ml?nb(C.parMl,2):'—'],['Base de prix',esc(base.version||'')+(base.at?' · '+dFR(base.at):'')]],body:zones+recap,css:'table.em td{text-align:right}table.em td:first-child{text-align:left}table.em{margin-bottom:10px}',footLeft:'SCR · commerce'});}
